# -*- coding: utf-8 -*-
"""Gera HTML estático. Uso: python3 scripts/build.py [--release]."""
import json, re, sys
from pathlib import Path
from html import escape
from urllib.parse import quote, urlparse
ROOT = Path(__file__).resolve().parent.parent
c = json.loads((ROOT / 'empresa.json').read_text())
out = ROOT / 'public'
out.mkdir(exist_ok=True)
e = lambda value: escape(str(value), quote=True)
pending = '<span class="pending">A confirmar antes da publicação</span>'
missing = [k for k in ('endereco', 'email', 'telefone', 'dominio', 'servicos', 'dados_confirmados') if not c.get(k)]
if c['email'] and not re.fullmatch(r'[^\s@]+@[^\s@]+\.[^\s@]+', c['email']):
    raise SystemExit('E-mail inválido')
if c['dominio'] and (urlparse(c['dominio']).scheme != 'https' or not urlparse(c['dominio']).netloc):
    raise SystemExit('dominio deve ser uma URL https completa')
if '--release' in sys.argv and missing:
    raise SystemExit('Publicação pendente: ' + ', '.join(missing))
brand = '<a class="brand" href="/" aria-label="TX Pay — início"><img src="/logo.svg" width="210" height="54" alt="TX Pay — Pagamentos e Tecnologia"></a>'
email = f'<a href="mailto:{e(c["email"])}">{e(c["email"])}</a>' if c['email'] else pending
phone = f'<a href="tel:{e(re.sub(r"[^+0-9]", "", c["telefone"]))}">{e(c["telefone"])}</a>' if c['telefone'] else pending
whatsapp_url = 'https://wa.me/' + re.sub(r'[^0-9]', '', c.get('whatsapp', ''))
whatsapp = f'<a href="{e(whatsapp_url)}" rel="noopener noreferrer">WhatsApp: {e(c["telefone"])}</a>'
address = e(c['endereco']) if c['endereco'] else pending
login_url = c.get('login_url') or '/login.html'
if c.get('login_url') and (urlparse(login_url).scheme != 'https' or not urlparse(login_url).netloc):
    raise SystemExit('login_url deve ser uma URL HTTPS completa')
header = f'''<a class="skip" href="#conteudo">Pular para o conteúdo</a>
{'<div class="draft">Prévia do projeto · Dados comerciais aguardando confirmação antes da publicação.</div>' if missing else ''}
<header class="header"><div class="wrap nav-bar">{brand}<button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation" aria-label="Principal"><a href="/#sobre">A empresa</a><a href="/#servicos">O que fazemos</a><a href="/#informacoes">Informações</a><a href="{e(login_url)}" class="button outline login-link">Login <span aria-hidden="true">↗</span></a><a href="/#contato" class="button">Fale com a TX <span aria-hidden="true">↗</span></a></nav></div></header>'''
footer = f'''<footer class="footer"><div class="wrap"><div class="footer-grid"><div class="footer-company">{brand}<p>TX Pay é a identificação utilizada neste site por<br><strong>{e(c['razao_social'])}</strong>.</p><p>CNPJ {e(c['cnpj'])}<br>{address}<br>Brasil</p></div><div class="footer-column"><h2>Atendimento</h2>{email}{phone}{whatsapp}<a href="/contato.html">Central de atendimento</a></div><div class="footer-column"><h2>Políticas e transparência</h2><a href="/privacidade.html">Política de Privacidade</a><a href="/cookies.html">Política de Cookies</a><a href="/termos.html">Termos de Uso</a><a href="/compras-entregas.html">Compras e Entregas</a><a href="/trocas-reembolsos.html">Trocas, Cancelamentos e Reembolsos</a></div></div><div class="copyright"><span>© 2026 {e(c['razao_social'])}. Todos os direitos reservados.</span><span>Site institucional · TX Pay</span></div></div></footer>'''

def page(filename, title, body, description):
    canonical = f'<link rel="canonical" href="{e(c["dominio"].rstrip("/"))}/{"" if filename == "index.html" else filename}">' if c['dominio'] else ''
    verification = f'<meta name="facebook-domain-verification" content="{e(c["meta_verification"])}">' if c['meta_verification'] else ''
    html = f'''<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)} | TX Pay</title><meta name="description" content="{e(description)}"><meta name="theme-color" content="#101c18"><meta name="robots" content="{'noindex, nofollow' if missing or filename == '404.html' else 'index, follow'}"><meta property="og:title" content="{e(title)} | TX Pay"><meta property="og:description" content="{e(description)}"><meta property="og:type" content="website"><meta property="og:locale" content="pt_BR">{canonical}{verification}<link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"><script src="/site.js" defer></script></head><body>{header}{body}{footer}</body></html>'''
    (out / filename).write_text(html)
services = ''
if c['servicos']:
    services = '<section class="section wrap" id="servicos"><div class="section-head"><div><span class="eyebrow">Nossa atuação</span><h2>Como podemos ajudar.</h2></div></div><div class="cards">' + ''.join(f'<article class="card"><span class="number">0{i+1}</span><h3>{e(s["titulo"])}</h3><p>{e(s["descricao"])}</p></article>' for i,s in enumerate(c['servicos'])) + '</div></section>'
body = f'''<main id="conteudo"><div class="wrap"><section class="hero"><div><span class="eyebrow">Pagamentos e Tecnologia TX</span><h1>Do digital ao físico.<br><em>Novas possibilidades<br>para você.</em></h1><p>{e(c['descricao'])}</p><div class="actions"><a href="#contato" class="button">Entre em contato <span aria-hidden="true">↗</span></a><a href="#informacoes" class="text-link">Conheça a empresa</a></div><div class="hero-note">{e(c['razao_social'])} · CNPJ {e(c['cnpj'])}</div></div><div class="art" aria-hidden="true"><div class="dot-grid"></div><div class="orbit"></div><div class="art-card"><div class="art-brand">tx pay ↗</div><div class="art-chip"><i></i><i></i><i></i><i></i></div><div class="small">DIGITAL. FÍSICO. POSSIBILIDADES.</div></div><div class="float-label"><strong>Um próximo passo</strong>começa com uma conversa. ↗</div></div></section><div class="strip"><span>Identificação da empresa</span><span>Canais de contato</span><span>Informações de privacidade</span></div><section class="section" id="sobre"><div class="section-head"><div><span class="eyebrow">Muito prazer, TX</span><h2>Clareza em cada conexão.</h2></div><p>A TX atua na venda de infoprodutos e produtos físicos e como correspondente de instituições financeiras. Aqui você encontra informações sobre a empresa e os canais para conhecer as opções disponíveis.</p></div><div class="cards"><article class="card"><span class="number">01 / EMPRESA</span><h3>Saiba com quem você fala.</h3><p>Razão social e CNPJ disponíveis para consulta em um só lugar.</p></article><article class="card"><span class="number">02 / CONTATO</span><h3>Atendimento próximo.</h3><p>Tire dúvidas sobre produtos, disponibilidade e condições de compra pelos canais comerciais.</p></article><article class="card"><span class="number">03 / TRANSPARÊNCIA</span><h3>Informação acessível.</h3><p>Consulte nossos termos de uso e saiba como os dados deste site são tratados.</p></article></div></section><section class="purpose" id="missao"><div><span class="eyebrow">Nosso horizonte</span><h2>Propósito para seguir.<br>Clareza para escolher.</h2></div><div class="purpose-list"><article><h3>Nossa missão</h3><p>Conectar pessoas a produtos e serviços com informação clara, atendimento acessível e respeito às necessidades de cada cliente.</p></article><article><h3>Nossa visão</h3><p>Construir relações duradouras e crescer com responsabilidade, ampliando as possibilidades de acesso a produtos digitais, físicos e serviços.</p></article><article><h3>Nossos valores</h3><p>Transparência nas informações, respeito ao consumidor, responsabilidade no atendimento e cuidado com os dados pessoais.</p></article></div></section></div>{services}<section class="light section" id="informacoes"><div class="wrap company"><div><span class="eyebrow">Informações institucionais</span><h2>Conheça a empresa<br>por trás da TX.</h2><p>TX Pay é a identificação utilizada neste site pela {e(c['razao_social'])}, responsável pelo conteúdo e pelos canais de atendimento abaixo.</p></div><dl class="data"><div><dt>Razão social</dt><dd>{e(c['razao_social'])}</dd></div><div><dt>CNPJ</dt><dd>{e(c['cnpj'])}</dd></div><div><dt>Endereço</dt><dd>{address}<br>Brasil</dd></div><div><dt>E-mail</dt><dd>{email}</dd></div><div><dt>Telefone</dt><dd>{phone}</dd></div><div><dt>Website</dt><dd><a href="{e(c['dominio'])}">{e(c['dominio'])}</a></dd></div></dl></div></section><section class="section wrap" id="contato"><div class="contact"><div><span class="eyebrow">Vamos conversar</span><h2>Seu próximo passo<br>começa aqui.</h2><p>Dúvidas sobre a empresa ou uma solicitação?<br>Utilize nossos canais de contato.</p></div><div><div class="contact-row"><div><small>E-MAIL COMERCIAL</small>{email}</div><span aria-hidden="true">↗</span></div><div class="contact-row"><div><small>TELEFONE E WHATSAPP</small>{phone}<br>{whatsapp}</div><span aria-hidden="true">↗</span></div><div class="contact-row"><div><small>ENDEREÇO DA EMPRESA</small>{address}</div></div></div></div><div class="faq"><span class="eyebrow">Dúvidas frequentes</span><details><summary>Qual empresa é responsável por este site?</summary><p>{e(c['razao_social'])}, inscrita no CNPJ {e(c['cnpj'])}. Consulte os dados institucionais acima.</p></details><details><summary>É possível contratar ou realizar pagamentos neste site?</summary><p>Este é um site institucional. Não há checkout, abertura de conta ou processamento de pagamentos nesta página. Consulte os canais comerciais para informações sobre a atuação da empresa.</p></details><details><summary>Como tratar uma solicitação sobre dados pessoais?</summary><p>Consulte a <a class="text-link" href="/privacidade.html">Política de Privacidade</a> e utilize o canal de contato indicado para exercer seus direitos.</p></details></div></section></main>'''
page('index.html','Pagamentos e Tecnologia TX',body,c['descricao'])
def legal(filename, title, content):
    page(filename,title,f'<main id="conteudo" class="wrap"><article class="legal"><a class="back" href="/">← Voltar ao início</a><h1>{title}</h1><p class="date">Versão de 3 de novembro de 2026</p>{content}</article></main>',title+' do site institucional da Pagamentos e Tecnologia TX LTDA.')
legal('privacidade.html','Política de Privacidade',f'''<p>Esta política explica o tratamento de dados relacionado ao site institucional de {e(c['razao_social'])}, CNPJ {e(c['cnpj'])}, responsável pelas decisões de tratamento descritas aqui. Endereço: {address}.</p><h2>1. Dados relacionados à navegação</h2><p>O site não possui cadastro, formulário de envio ou checkout. O código do site não instala ferramentas de publicidade, Meta Pixel ou análise de audiência. A infraestrutura de hospedagem pode processar dados técnicos, como endereço IP, data e horário, URL acessada e informações do navegador, para entregar as páginas e proteger o serviço.</p><h2>2. Contatos iniciados por você</h2><p>Ao entrar em contato por e-mail, telefone ou WhatsApp, poderemos receber seu nome, seus dados de contato e o conteúdo da solicitação. Esses dados são usados para responder à mensagem e, quando aplicável, conduzir procedimentos preliminares de contratação solicitados por você. Evite enviar senhas, dados completos de cartão ou documentos sem necessidade.</p><p>Os links de WhatsApp abrem um serviço externo da Meta. O número e as mensagens que você enviar serão tratados também nesse serviço, conforme sua própria política de privacidade. O simples acesso ao site não envia uma mensagem e não autoriza o recebimento de publicidade.</p><h2>3. Finalidades e bases legais</h2><p>Os dados são tratados conforme a finalidade: atendimento de solicitações e medidas pré-contratuais a seu pedido; cumprimento de obrigações legais; e interesses legítimos de segurança e funcionamento, observados os direitos do titular. Caso uma atividade dependa de consentimento, ele deverá ser solicitado de forma específica e poderá ser revogado.</p><h2>4. Prestadores e armazenamento</h2><p>Prestadores de hospedagem, e-mail e telecomunicações podem processar informações necessárias à prestação de seus serviços. No caso de hospedagem na Vercel, o processamento segue também as condições desse provedor e pode envolver infraestrutura no exterior. Transferências internacionais devem observar os mecanismos aplicáveis da LGPD. Informações também podem ser fornecidas para atender obrigações legais e solicitações válidas de autoridades.</p><h2>5. Conservação e segurança</h2><p>A conservação deve se limitar ao tempo necessário à finalidade do contato, ao cumprimento de obrigações legais e ao exercício regular de direitos. Os períodos dependem da categoria do dado e do serviço utilizado. Solicitações de eliminação são analisadas considerando as hipóteses legais de retenção. O acesso aos dados deve ser limitado às pessoas e prestadores que precisam deles para essas finalidades.</p><h2>6. Seus direitos</h2><p>Você pode solicitar confirmação de tratamento, acesso, correção, informações sobre compartilhamento, anonimização, bloqueio ou eliminação nas hipóteses legais, portabilidade conforme regulamentação, e revogação do consentimento. Também pode se opor ao tratamento irregular e apresentar petição à ANPD. Poderá ser solicitada confirmação de identidade proporcional ao pedido.</p><h2>7. Canal de privacidade</h2><p>Envie sua solicitação para: {email}. Identifique o pedido como “Privacidade e dados pessoais” e descreva o direito que deseja exercer.</p><h2>8. Atualizações</h2><p>Alterações nas funcionalidades e no tratamento de dados deverão ser refletidas nesta política, com atualização da data desta página.</p>''')
legal('termos.html','Termos de Uso',f'''<p>Estes termos se aplicam ao site institucional de {e(c['razao_social'])}, CNPJ {e(c['cnpj'])}. Endereço: {address}. Contato: {email}.</p><h2>1. Finalidade do site</h2><p>O site disponibiliza informações institucionais e canais de contato. Não realiza transações financeiras, abertura de contas ou contratação automática. A empresa atua na comercialização de infoprodutos e produtos físicos e como correspondente de instituições financeiras. Informações sobre os serviços de correspondente, as instituições envolvidas e as condições de atendimento devem ser consultadas pelos canais de contato. Qualquer compra depende da identificação do produto e das condições específicas apresentadas antes da contratação.</p><h2>2. Informações e propostas</h2><p>O conteúdo institucional não substitui uma proposta comercial ou contrato. Preços, escopo, disponibilidade, responsabilidades e condições de cancelamento ou reembolso, quando aplicáveis, devem ser informados antes da contratação do serviço correspondente.</p><h2>Compras, entrega e atendimento</h2><p>Antes de concluir uma compra, consulte a descrição do produto, preço total, eventuais despesas de entrega, forma de pagamento e prazo. Para infoprodutos, verifique também o formato, os requisitos e o prazo de acesso. Dúvidas sobre pedidos, cancelamentos, devoluções ou reembolsos podem ser encaminhadas aos canais comerciais. Os direitos previstos na legislação de defesa do consumidor permanecem assegurados; condições específicas devem ser informadas no canal em que a compra ocorrer.</p><h2>3. Uso adequado</h2><p>Utilize os canais para solicitações legítimas. Não é permitido utilizar o site para fraude, inserção de conteúdo malicioso, violação de direitos de terceiros ou tentativas de acesso não autorizado.</p><h2>4. Conteúdo e links</h2><p>Os elementos visuais e textos do site estão sujeitos aos direitos de seus respectivos titulares. Referências a páginas externas não significam que a TX controla seus conteúdos ou políticas.</p><h2>5. Disponibilidade</h2><p>O site pode passar por manutenções ou interrupções. Caso identifique informações incorretas ou dificuldades de acesso, comunique pelo canal de contato. Estes termos não excluem responsabilidades ou direitos previstos na legislação aplicável.</p><h2>6. Dados pessoais</h2><p>O tratamento de dados relacionado ao site está descrito na <a href="/privacidade.html">Política de Privacidade</a>.</p><h2>7. Legislação e contato</h2><p>Aplica-se a legislação brasileira, respeitados os direitos do consumidor quando cabíveis. Para dúvidas, reclamações ou solicitações, entre em contato: {email}.</p>''')
legal('cookies.html','Política de Cookies','''<p>O código deste site não define cookies nem utiliza armazenamento local no navegador. Não há Meta Pixel, publicidade comportamental, vídeos incorporados, fontes externas ou ferramentas de análise de audiência instaladas.</p><h2>Hospedagem</h2><p>A infraestrutura de hospedagem pode processar registros técnicos de acesso para operação e segurança. Consulte a Política de Privacidade para mais informações. Essa prática não implica a instalação de cookies publicitários pelo código do site.</p><h2>Links de contato</h2><p>Ao abrir um link de e-mail, telefone ou WhatsApp, você utiliza o aplicativo correspondente no seu dispositivo. Esse serviço possui suas próprias condições de privacidade.</p><h2>Mudanças nas ferramentas</h2><p>Se novas ferramentas que dependam de cookies forem adicionadas, esta página e a política de privacidade deverão ser atualizadas, e os controles de consentimento deverão ser implementados quando necessários.</p><p><a href="/privacidade.html">Consultar Política de Privacidade →</a></p>''')
legal('contato.html', 'Central de atendimento', f'''<p>Fale com a {e(c['razao_social'])}, CNPJ {e(c['cnpj'])}, responsável pelo site TX Pay.</p><h2>Fale com a empresa</h2><div class="contact-panel"><p>E-mail: {email}</p><p>Telefone: {phone}</p><p>{whatsapp}</p><p>Endereço: {address}, Brasil.</p></div><h2>Produtos e pedidos</h2><p>Para consultar produtos, entrega ou acesso a um infoproduto, informe o item de interesse. Para pedidos existentes, inclua a referência do pedido, se disponível, e descreva sua solicitação. Não envie senhas ou dados completos de cartão.</p><h2>Trocas, cancelamentos e reclamações</h2><p>Os mesmos canais atendem solicitações de pós-venda. Consulte a <a href="/trocas-reembolsos.html">política de trocas, cancelamentos e reembolsos</a> e a <a href="/compras-entregas.html">política de compras e entregas</a>.</p><h2>Privacidade e dados pessoais</h2><p>Para pedidos de acesso, correção ou eliminação de dados, escreva para {email} com o assunto “Privacidade e dados pessoais”. Consulte a <a href="/privacidade.html">Política de Privacidade</a>.</p>''')
legal('compras-entregas.html', 'Política de Compras e Entregas', f'''<p>Estas informações se aplicam à venda de infoprodutos e produtos físicos por {e(c['razao_social'])}, CNPJ {e(c['cnpj'])}. Este site é institucional e não possui checkout.</p><h2>1. Informações antes da compra</h2><p>Antes de concluir uma compra, consulte a descrição do item, suas características e restrições, disponibilidade, preço total, forma de pagamento, despesas adicionais e condições de entrega ou acesso. As condições específicas devem constar da oferta e da confirmação do pedido. Não há preço ou prazo único aplicável a todos os produtos.</p><h2>2. Produtos físicos</h2><p>O prazo de envio e entrega, a área atendida e o valor do frete devem ser informados antes da conclusão do pedido, considerando o produto e o endereço de destino. Confira os dados de entrega e comunique eventuais erros pelos canais de atendimento. Em caso de atraso, item divergente ou avaria, entre em contato para solicitar a solução cabível, preservados seus direitos.</p><h2>3. Infoprodutos</h2><p>A oferta deve identificar o conteúdo, formato, requisitos de uso, forma de disponibilização e prazo de acesso. Se houver dificuldade de acesso ou divergência em relação ao conteúdo contratado, entre em contato informando o produto e a referência da compra, quando disponível.</p><h2>4. Acompanhamento e atendimento</h2><p>Solicite informações sobre seu pedido pelo e-mail {email}, telefone {phone} ou {whatsapp}. Não envie senhas ou códigos de autenticação.</p><h2>5. Cancelamentos e devoluções</h2><p>Consulte a <a href="/trocas-reembolsos.html">Política de Trocas, Cancelamentos e Reembolsos</a>. Estas informações não limitam direitos assegurados pela legislação.</p><h2>6. Serviços de correspondente</h2><p>Esta política trata das compras de produtos físicos e digitais. Para serviços de correspondente, as instituições envolvidas, os serviços disponíveis e as condições específicas devem ser identificados antes de qualquer contratação.</p>''')
legal('trocas-reembolsos.html', 'Trocas, Cancelamentos e Reembolsos', f'''<p>Esta política orienta clientes de {e(c['razao_social'])}, CNPJ {e(c['cnpj'])}, sobre solicitações relacionadas a produtos físicos e infoprodutos.</p><h2>1. Como solicitar</h2><p>Entre em contato pelo e-mail {email}, telefone {phone} ou {whatsapp}. Informe o produto, a referência do pedido, se disponível, e o que deseja solicitar. Para exercer o direito de arrependimento, não é necessário justificar sua decisão.</p><h2>2. Direito de arrependimento</h2><p>Nas compras realizadas fora do estabelecimento comercial, o consumidor pode exercer o direito de arrependimento em sete dias corridos, contados da assinatura do contrato ou do recebimento do produto ou serviço, conforme o caso e o artigo 49 do Código de Defesa do Consumidor. Os valores pagos devem ser restituídos integralmente nos termos da lei, sem custos adicionais pelo exercício desse direito.</p><h2>3. Devolução de produtos físicos</h2><p>Solicite pelos canais de atendimento as orientações para devolução do item. No exercício do direito legal de arrependimento, a devolução não deve gerar custo adicional ao consumidor. Problemas de entrega, avarias, defeitos ou divergências devem ser comunicados para encaminhamento da solução cabível.</p><h2>4. Produtos digitais</h2><p>Para infoprodutos, identifique o conteúdo adquirido e a forma de acesso. As condições da oferta e da plataforma de entrega não afastam os direitos previstos na legislação aplicável. Dificuldades de acesso e conteúdo diferente do contratado também podem ser comunicados pelos canais de atendimento.</p><h2>5. Trocas e defeitos</h2><p>As garantias legais e os direitos decorrentes de defeito ou descumprimento da oferta permanecem assegurados. Trocas por preferência fora das hipóteses legais dependem das condições expressamente oferecidas antes da compra. Não há garantia comercial adicional anunciada nesta página.</p><h2>6. Reembolsos</h2><p>O atendimento informará o encaminhamento da restituição e a forma de acompanhamento conforme o meio de pagamento utilizado, respeitados os prazos e direitos legais. Não é exigido pagamento de taxa para solicitar um reembolso devido.</p><h2>7. Escopo</h2><p>Esta política trata da venda de produtos físicos e digitais. Solicitações relativas a serviços de correspondente devem considerar também o contrato e os canais da instituição responsável pela operação, sem prejuízo dos direitos aplicáveis.</p><p>Referência: <a href="https://www.planalto.gov.br/ccivil_03/leis/l8078compilado.htm">Código de Defesa do Consumidor</a>.</p>''')
page('login.html', 'Área do cliente', '<main id="conteudo" class="wrap legal"><span class="eyebrow">TX Pay · Área do cliente</span><h1>Acesso à sua conta.</h1><p>A área de login ainda não está disponível neste site.</p><p>Para informações sobre seus produtos ou pedidos, entre em contato com a equipe TX.</p><div class="actions"><a class="button" href="/contato.html">Falar com o atendimento ↗</a><a class="text-link" href="/">Voltar ao início</a></div></main>', 'Informações de acesso à área do cliente TX Pay.')
page('404.html','Página não encontrada','<main id="conteudo" class="wrap legal"><span class="eyebrow">Erro 404</span><h1>Esse caminho<br>não existe.</h1><p>A página pode ter mudado de endereço.</p><a class="button" href="/">Voltar ao início →</a></main>','Página não encontrada.')
(out/'robots.txt').write_text('User-agent: *\nDisallow: /\n' if missing else 'User-agent: *\nAllow: /\nSitemap: '+c['dominio'].rstrip('/')+'/sitemap.xml\n')
if c['dominio']:
    (out/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+e(c['dominio'].rstrip('/')+'/'+p)+'</loc></url>' for p in ('','contato.html','privacidade.html','termos.html','cookies.html','compras-entregas.html','trocas-reembolsos.html'))+'</urlset>')
elif (out/'sitemap.xml').exists():
    (out/'sitemap.xml').unlink()
